import "../../styles/index-base.css";
import "../../styles/components/date-picker.css";
import {
  Button as AriaButton,
  Calendar as AriaCalendar,
  CalendarCell,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHeader,
  CalendarHeaderCell,
  DateInput,
  DatePicker as AriaDatePicker,
  DateSegment,
  Dialog as AriaDialog,
  Group,
  Heading,
  Label,
  Popover,
  Text,
  type CalendarProps as AriaCalendarProps,
  type DatePickerProps as AriaDatePickerProps,
  type DateValue,
} from "react-aria-components";
import { CalendarBlank, CaretLeft, CaretRight } from "@phosphor-icons/react";
import type { ReactNode } from "react";
import { cn } from "../../lib/cn";

export type CalendarProps<T extends DateValue> = Omit<AriaCalendarProps<T>, "children" | "className"> & {
  className?: string;
};

export function Calendar<T extends DateValue>({ className, ...props }: CalendarProps<T>) {
  return (
    <AriaCalendar className={cn("ix-calendar", className)} {...props}>
      <header className="ix-calendar__header">
        <AriaButton slot="previous" className="ix-calendar__nav" aria-label="Previous month">
          <CaretLeft aria-hidden="true" />
        </AriaButton>
        <Heading className="ix-calendar__heading" />
        <AriaButton slot="next" className="ix-calendar__nav" aria-label="Next month">
          <CaretRight aria-hidden="true" />
        </AriaButton>
      </header>
      <CalendarGrid className="ix-calendar__grid" weekdayStyle="short">
        <CalendarGridHeader>
          {(day) => <CalendarHeaderCell className="ix-calendar__weekday">{day}</CalendarHeaderCell>}
        </CalendarGridHeader>
        <CalendarGridBody>
          {(date) => <CalendarCell className="ix-calendar__cell" date={date} />}
        </CalendarGridBody>
      </CalendarGrid>
    </AriaCalendar>
  );
}

export type DatePickerProps<T extends DateValue> = Omit<AriaDatePickerProps<T>, "children" | "className"> & {
  label?: ReactNode;
  "aria-label"?: string;
  description?: ReactNode;
  errorMessage?: ReactNode;
  className?: string;
};

export function DatePicker<T extends DateValue>({
  label,
  "aria-label": ariaLabel,
  description,
  errorMessage,
  className,
  ...props
}: DatePickerProps<T>) {
  return (
    <AriaDatePicker
      aria-label={label ? undefined : ariaLabel}
      className={cn("ix-date-picker", className)}
      isInvalid={Boolean(errorMessage) || props.isInvalid}
      {...props}
    >
      {label && <Label className="ix-field__label">{label}</Label>}
      <Group className="ix-date-picker__group">
        <DateInput className="ix-date-picker__input">
          {(segment) => <DateSegment className="ix-date-picker__segment" segment={segment} />}
        </DateInput>
        <AriaButton className="ix-date-picker__button" aria-label="Open calendar">
          <CalendarBlank aria-hidden="true" />
        </AriaButton>
      </Group>
      {description && <Text slot="description" className="ix-field__description">{description}</Text>}
      {errorMessage && <Text slot="errorMessage" className="ix-field__error">{errorMessage}</Text>}
      <Popover className="ix-date-picker__popover" placement="bottom start" data-layer="flyout">
        <AriaDialog className="ix-date-picker__dialog">
          <Calendar />
        </AriaDialog>
      </Popover>
    </AriaDatePicker>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-field__label { color: var(--ix-ink); font-size: 12px; font-weight: 550; }

.ix-field__description,
.ix-field__error { color: var(--ix-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.ix-field__error { color: var(--ix-fg-danger); font-weight: 520; }

.ix-date-picker { display: grid; width: min(240px, 100%); gap: 6px; color: var(--ix-fg-default); }

.ix-date-picker__group {
  display: flex;
  width: 100%;
  height: 32px;
  align-items: center;
  border: 1px solid var(--ix-control-border);
  border-radius: var(--ix-radius-sm);
  background: var(--ix-bg-control);
  box-shadow: var(--ix-shadow-control);
  transition: border-color var(--ix-hover-duration), box-shadow var(--ix-hover-duration), background-color var(--ix-hover-duration);
}

.ix-date-picker__group[data-hovered] { border-color: var(--ix-control-border-hover); }

.ix-date-picker[data-focus-within] .ix-date-picker__group { border-color: var(--ix-control-border-hover); }

.ix-date-picker[data-invalid] .ix-date-picker__group { border-color: var(--ix-fg-danger); }

.ix-date-picker[data-disabled] { color: var(--ix-fg-disabled); }

.ix-date-picker[data-disabled] .ix-date-picker__group { background: var(--ix-bg-subtle); box-shadow: none; }

.ix-date-picker__input { display: flex; min-width: 0; flex: 1; align-items: center; padding-left: 10px; font-size: var(--ix-type-ui); }

.ix-date-picker__segment { min-width: .65ch; border-radius: 3px; outline: 0; color: inherit; font-variant-numeric: tabular-nums; }

.ix-date-picker__segment:not([data-type="literal"]) { display: inline-grid; min-width: 24px; min-height: 24px; place-items: center; }

.ix-date-picker__segment[data-placeholder] { color: var(--ix-fg-subtle); }

.ix-date-picker__segment[data-focused] { background: var(--ix-selection); color: var(--ix-fg-default); }

.ix-date-picker__button { display: grid; width: 30px; height: 30px; place-items: center; border: 0; border-radius: 5px; background: transparent; color: var(--ix-fg-muted); cursor: pointer; }

.ix-date-picker__button:hover { background: var(--ix-hover); color: var(--ix-fg-default); }

.ix-date-picker__button:focus-visible { outline: 0; box-shadow: inset 0 0 0 1px var(--ix-focus-control); }

.ix-date-picker__button svg { width: 14px; height: 14px; }

.ix-date-picker__popover {
  border-radius: var(--ix-radius-overlay);
  background: color-mix(in oklab, var(--ix-bg-flyout) 96%, transparent);
  box-shadow: var(--ix-shadow-flyout);
  backdrop-filter: blur(14px);
  transform-origin: var(--trigger-anchor-point);
  transition: opacity var(--ix-enter-duration) var(--ix-ease-out), transform var(--ix-enter-duration) var(--ix-ease-out);
}

.ix-date-picker__popover[data-entering],
.ix-date-picker__popover[data-exiting] { opacity: 0; transform: translateY(-2px) scale(.985); }

.ix-date-picker__dialog { outline: 0; }

.ix-calendar { width: 258px; padding: 10px; color: var(--ix-fg-default); }

.ix-calendar__header { display: grid; grid-template-columns: 28px 1fr 28px; align-items: center; margin-bottom: 6px; }

.ix-calendar__heading { margin: 0; font-size: var(--ix-type-ui); font-weight: 590; text-align: center; }

.ix-calendar__nav { display: grid; width: 28px; height: 28px; place-items: center; border: 0; border-radius: 6px; background: transparent; color: var(--ix-fg-muted); cursor: pointer; }

.ix-calendar__nav:hover { background: var(--ix-hover); color: var(--ix-fg-default); }

.ix-calendar__nav:focus-visible { outline: 0; box-shadow: inset 0 0 0 1px var(--ix-focus-control); }

.ix-calendar__nav svg { width: 13px; height: 13px; }

.ix-calendar__grid { width: 100%; border-collapse: separate; border-spacing: 1px; table-layout: fixed; }

.ix-calendar__weekday { height: 24px; color: var(--ix-fg-subtle); font-size: 10.5px; font-weight: 520; text-align: center; }

.ix-calendar__cell { width: 30px; height: 30px; border-radius: 6px; color: var(--ix-fg-muted); font-size: var(--ix-type-label); text-align: center; cursor: pointer; }

.ix-calendar__cell[data-hovered] { background: var(--ix-hover); color: var(--ix-fg-default); }

.ix-calendar__cell[data-selected] { background: var(--ix-fg-default); color: var(--ix-bg-canvas); font-weight: 620; }

.ix-calendar__cell[data-today]:not([data-selected]) { box-shadow: inset 0 0 0 1px var(--ix-control-border-hover); color: var(--ix-fg-default); }

.ix-calendar__cell[data-outside-month] { color: var(--ix-fg-disabled); }

.ix-calendar__cell[data-unavailable] { color: var(--ix-fg-subtle); text-decoration: line-through; }

.ix-calendar__cell[data-disabled] { opacity: .42; cursor: not-allowed; }

.ix-calendar__cell[data-focus-visible] { outline: 0; box-shadow: inset 0 0 0 2px var(--ix-focus-control); }

@media (prefers-reduced-motion: reduce) {
.ix-date-picker__popover { transition-duration: 0.01ms; }
}
}
